// A Blitz tower round on a real map, worked out from real data.
//
// The map data (lib/tournament/towerMaps/<map>.json) is generated by the plugin
// repo's blitz_kit/generators/site_map.py: the floor is the map's nav mesh seen
// from above, the zones are where the server stands the tower (the bomb sites'
// plant spots and the field spots), the spawns are the ones it hands out
// (R5eGames.Tournament/tower_spawns), and every route is the nav mesh's walking path
// pulled tight, with the time it takes at rifle speed — from each spawn to each
// tower spot, and from each team's classic spawn (where a respawn comes back).
// Nothing here is drawn by hand.
//
// The rules are the plugin's, from R5eGames.Tournament.Core/Match/TowerRound.cs,
// Match/TowerController.cs and Match/RespawnController.cs. Keep these numbers in step.

import dust2 from "./towerMaps/de_dust2.json";

/** Play before the final countdown starts (t_tower_final_after). */
export const FINAL_AFTER = 120;
/** Holding E at the tower, everybody but the Engineer. */
export const ACTIVATE_SECONDS = 3;
/** Holding E at the tower, the Engineer. */
export const ENGINEER_SECONDS = 1.5;
/** What every activation puts on the clock, and the final countdown's length. */
export const COUNTDOWN_SECONDS = 20;
/** A dead player is back after this (t_respawn_delay), at the team's classic spawn. */
export const RESPAWN_SECONDS = 5;

export type Side = "t" | "ct";
export type Group = "t" | "ct" | "roamer";

export type MapPoint = { name: string; role: string | null; x: number; y: number; yaw: number };
export type MapRoute = { d: string; len: number; secs: number };
export type ZoneRoutes = Record<Group, MapRoute[]> & { respawn: Record<Side, MapRoute> };
export type MapZone = {
  zone: number;
  kind: "site" | "field";
  name: string;
  spots: MapPoint[];
  t: MapPoint[];
  ct: MapPoint[];
  roamer: MapPoint[];
  /** routes[spot]: per group, one per spawn of that group; and the two respawn routes. */
  routes: ZoneRoutes[];
};
export type TowerMap = {
  map: string;
  scale: number;
  run: number;
  bounds: number[];
  floor: string;
  upper: string;
  labels: { name: string; x: number; y: number; size: number }[];
  /** The classic team spawns, where a respawned player comes back. */
  bases: Record<Side, { name: string; x: number; y: number }>;
  zones: MapZone[];
};

export const TOWER_MAPS: Record<string, TowerMap> = {
  de_dust2: dust2 as TowerMap,
};

export const needFor = (role: string | null) => (role === "engineer" ? ENGINEER_SECONDS : ACTIVATE_SECONDS);

/** One run in a scenario: a route from `start` (seconds), then maybe holding E, maybe going down. */
export type Actor = {
  /** Which routes it runs: a group's spawn route, or a side's respawn route. */
  group: Group | "respawn";
  /** Index into the zone's spawns of that group (0 for a respawn). */
  index: number;
  side: Side;
  role: string;
  from: string;
  start: number;
  arrive: number;
  holds: { from: number; to: number; need: number; done: boolean }[];
  /** Goes down at this time, if at all. */
  out?: number;
};

export type Step = { at: number | null; key: string; vars?: Record<string, string | number> };

export type Scenario = {
  id: ScenarioId;
  actors: Actor[];
  /** Ownership changes, in order. `resets`: the countdown starts again (always, before the final one). */
  captures: { at: number; side: Side; resets: boolean }[];
  /** Simulated seconds the scenario runs for. */
  end: number;
  /** Playback speed: the stand-off fast-forwards its two minutes. */
  speed: number;
  steps: Step[];
  outcome: Step;
};

export const SCENARIOS = ["race", "takeover", "respawn", "roamer", "standoff"] as const;
export type ScenarioId = (typeof SCENARIOS)[number];

const r1 = (n: number) => Math.round(n * 10) / 10;
const other = (s: Side): Side => (s === "t" ? "ct" : "t");

/** The player of a group who would have the tower activated soonest, running and holding. */
function quickest(zone: MapZone, spot: number, group: Group, side: Side): Actor {
  const routes = zone.routes[spot][group];
  const people = zone[group];
  let best = 0;
  let bestDone = Infinity;
  people.forEach((p, i) => {
    const done = routes[i].secs + needFor(p.role);
    if (done < bestDone) {
      best = i;
      bestDone = done;
    }
  });
  const p = people[best];
  return {
    group, index: best, side, role: p.role ?? (side === "t" ? "rifler" : "frontrunner"), from: p.name,
    start: 0, arrive: routes[best].secs, holds: [],
  };
}

/** The first activation, both teams sprinting from freeze time. */
function raceCore(zone: MapZone, spot: number) {
  const t = quickest(zone, spot, "t", "t");
  const ct = quickest(zone, spot, "ct", "ct");
  const tDone = t.arrive + needFor(t.role);
  const ctDone = ct.arrive + needFor(ct.role);
  const winner: Side = tDone < ctDone ? "t" : "ct";
  const at = r1(Math.min(tDone, ctDone));
  const [win, lose] = winner === "t" ? [t, ct] : [ct, t];
  win.holds.push({ from: win.arrive, to: at, need: needFor(win.role), done: true });
  if (lose.arrive < at) lose.holds.push({ from: lose.arrive, to: at, need: needFor(lose.role), done: false });
  return { win, lose, winner, at, margin: r1(Math.abs(tDone - ctDone)) };
}

const arriveStep = (a: Actor): Step => ({
  at: r1(a.arrive),
  key: "home.round.step.arrive",
  vars: { role: a.role, from: a.from, need: needFor(a.role) },
});

const byTime = (a: Step, b: Step) => (a.at ?? 0) - (b.at ?? 0);

export function scenario(map: TowerMap, zoneIndex: number, spot: number, id: ScenarioId): Scenario {
  const zone = map.zones[zoneIndex];
  const spotName = zone.spots[spot].name;
  const start: Step = { at: 0, key: "home.round.step.start", vars: { spot: spotName } };

  if (id === "race" || id === "takeover" || id === "respawn") {
    const { win, lose, winner, at, margin } = raceCore(zone, spot);
    const steps: Step[] = [start, ...[win, lose].map(arriveStep).sort(byTime)];
    steps.push({ at, key: "home.round.step.capture", vars: { team: winner } });
    if (lose.holds.length) steps.push({ at, key: "home.round.step.cut", vars: { role: lose.role } });
    const captures = [{ at, side: winner, resets: true }];

    if (id === "race") {
      return {
        id, actors: [win, lose], captures, end: at + 2.5, speed: 1, steps,
        outcome: { at: null, key: "home.round.out.race", vars: { team: winner, role: win.role, at, margin } },
      };
    }

    if (id === "takeover") {
      // The side that lost the race goes again from zero, and wins back 20 s.
      const from = r1(Math.max(lose.arrive, at));
      const to = r1(from + needFor(lose.role));
      lose.holds.push({ from, to, need: needFor(lose.role), done: true });
      captures.push({ at: to, side: other(winner), resets: true });
      steps.push({ at: from, key: "home.round.step.again", vars: { role: lose.role, need: needFor(lose.role) } });
      steps.push({ at: to, key: "home.round.step.takeover", vars: { team: other(winner) } });
      steps.push({ at: null, key: "home.round.step.zero" });
      return {
        id, actors: [win, lose], captures, end: to + 2.5, speed: 1, steps,
        outcome: { at: null, key: "home.round.out.takeover" },
      };
    }

    // Respawn: the loser of the race goes down at the tower, is back 5 s later at the
    // classic spawn, and runs the long way to take the tower back — if the 20 s allow it.
    const dies = r1(Math.max(lose.arrive, at) + 0.5);
    lose.out = dies;
    const back = r1(dies + RESPAWN_SECONDS);
    const run = zone.routes[spot].respawn[lose.side];
    const base = map.bases[lose.side];
    const again: Actor = {
      group: "respawn", index: 0, side: lose.side, role: lose.role, from: base.name,
      start: back, arrive: r1(back + run.secs), holds: [],
    };
    const deadline = at + COUNTDOWN_SECONDS;
    steps.push({ at: dies, key: "home.round.step.down", vars: { role: lose.role } });
    steps.push({ at: back, key: "home.round.step.back", vars: { role: lose.role, from: base.name } });
    const to = r1(again.arrive + needFor(lose.role));
    if (to < deadline) {
      again.holds.push({ from: again.arrive, to, need: needFor(lose.role), done: true });
      captures.push({ at: to, side: lose.side, resets: true });
      steps.push({ at: again.arrive, key: "home.round.step.runback", vars: { secs: run.secs, need: needFor(lose.role) } });
      steps.push({ at: to, key: "home.round.step.takeover", vars: { team: lose.side } });
      return {
        id, actors: [win, lose, again], captures, end: to + 2.5, speed: 1, steps,
        outcome: { at: null, key: "home.round.out.respawn", vars: { secs: run.secs, from: base.name } },
      };
    }
    steps.push({ at: r1(deadline), key: "home.round.step.toolate", vars: { team: winner, secs: run.secs } });
    return {
      id, actors: [win, lose, again], captures, end: r1(deadline), speed: 1, steps,
      outcome: { at: null, key: "home.round.out.respawnLate", vars: { secs: run.secs, from: base.name } },
    };
  }

  if (id === "roamer") {
    const t = quickest(zone, spot, "t", "t");
    const routes = zone.routes[spot].roamer;
    if (routes.length === 0) return scenario(map, zoneIndex, spot, "race");
    let ri = 0;
    routes.forEach((r, i) => { if (r.secs < routes[ri].secs) ri = i; });
    const roamer: Actor = {
      group: "roamer", index: ri, side: "ct", role: "roamer", from: zone.roamer[ri].name,
      start: 0, arrive: routes[ri].secs, holds: [],
    };
    const tDone = t.arrive + needFor(t.role);
    const steps: Step[] = [start, { at: 0, key: "home.round.step.hidden", vars: { from: roamer.from } }];
    const captures: Scenario["captures"] = [];
    // The duel: the Roamer is at the tower before the T has it, or arrives behind a T
    // who already does. Either way it starts with the angle.
    const duel = r1(Math.max(roamer.arrive, t.arrive) + 0.4);
    if (roamer.arrive < tDone) {
      if (t.arrive < duel) t.holds.push({ from: t.arrive, to: Math.min(duel, tDone), need: needFor(t.role), done: false });
      t.out = duel;
      steps.push({ at: r1(roamer.arrive), key: "home.round.step.flank" });
      steps.push(arriveStep(t));
      steps.sort(byTime);
      steps.push({ at: duel, key: "home.round.step.caught", vars: { role: t.role } });
    } else {
      t.holds.push({ from: t.arrive, to: r1(tDone), need: needFor(t.role), done: true });
      captures.push({ at: r1(tDone), side: "t", resets: true });
      t.out = duel;
      steps.push(arriveStep(t));
      steps.push({ at: r1(tDone), key: "home.round.step.capture", vars: { team: "t" } });
      steps.push({ at: r1(roamer.arrive), key: "home.round.step.behind" });
      steps.push({ at: duel, key: "home.round.step.caught", vars: { role: t.role } });
    }
    const to = r1(duel + ACTIVATE_SECONDS);
    roamer.holds.push({ from: duel, to, need: ACTIVATE_SECONDS, done: true });
    const first = captures.length === 0;
    captures.push({ at: to, side: "ct", resets: true });
    steps.push({ at: to, key: first ? "home.round.step.capture" : "home.round.step.takeover", vars: { team: "ct" } });
    return {
      id, actors: [t, roamer], captures, end: to + 2.5, speed: 1, steps,
      outcome: { at: null, key: "home.round.out.roamer", vars: { from: roamer.from, secs: r1(roamer.arrive) } },
    };
  }

  // The stand-off: nobody commits; at 2:00 the final countdown, then a draw.
  const end = FINAL_AFTER + COUNTDOWN_SECONDS;
  return {
    id, actors: [], captures: [], end, speed: 35,
    steps: [
      start,
      { at: null, key: "home.round.step.wait" },
      { at: FINAL_AFTER, key: "home.round.step.final" },
      { at: end, key: "home.round.step.draw" },
    ],
    outcome: { at: null, key: "home.round.out.standoff" },
  };
}

/** The final countdown is running at simulated time `t`. */
export const finalAt = (t: number) => t >= FINAL_AFTER;

/** Seconds on the round clock at simulated time `t`: to 2:00 while dormant, then the countdowns. */
export function clockAt(s: Scenario, t: number): number {
  if (t >= FINAL_AFTER) return Math.max(0, FINAL_AFTER + COUNTDOWN_SECONDS - t);
  let last: number | null = null;
  for (const c of s.captures) if (c.at <= t && c.resets) last = c.at;
  if (last === null) return Math.max(0, FINAL_AFTER - t);
  return Math.max(0, COUNTDOWN_SECONDS - (t - last));
}

/** Who holds the tower at `t`, or null while it is dormant. */
export function ownerAt(s: Scenario, t: number): Side | null {
  let owner: Side | null = null;
  for (const c of s.captures) if (c.at <= t) owner = c.side;
  return owner;
}

export const formatClock = (secs: number) => {
  const s = Math.ceil(secs - 1e-6);
  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}`;
};

/** The route an actor runs. */
export const routeOf = (zone: MapZone, spot: number, a: Actor): MapRoute =>
  a.group === "respawn" ? zone.routes[spot].respawn[a.side] : zone.routes[spot][a.group][a.index];

/** A route's polyline, for moving a player along it without the DOM. */
export function polyline(d: string) {
  const pts = d.slice(1).split("L").map((p) => p.trim().split(/\s+/).map(Number) as [number, number]);
  const acc = [0];
  for (let i = 1; i < pts.length; i++) acc.push(acc[i - 1] + Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]));
  return { pts, acc, total: acc[acc.length - 1] };
}

export function pointAlong(line: ReturnType<typeof polyline>, frac: number): [number, number] {
  const f = Math.min(1, Math.max(0, frac));
  const want = f * line.total;
  let i = 1;
  while (i < line.acc.length - 1 && line.acc[i] < want) i++;
  const seg = line.acc[i] - line.acc[i - 1] || 1;
  const k = (want - line.acc[i - 1]) / seg;
  const [x0, y0] = line.pts[i - 1];
  const [x1, y1] = line.pts[Math.min(i, line.pts.length - 1)];
  return [x0 + (x1 - x0) * k, y0 + (y1 - y0) * k];
}

/**
 * Where an actor is at `t`: on its route, stopping short of the tower (so two players
 * at the tower stand either side of it, as they would, not on one pixel).
 */
export function actorAt(line: ReturnType<typeof polyline>, a: Actor, t: number, stopShort: number): [number, number] {
  const span = Math.max(0.01, a.arrive - a.start);
  const frac = Math.min(1, Math.max(0, (t - a.start) / span));
  const reach = Math.max(0, line.total - stopShort) / (line.total || 1);
  return pointAlong(line, frac * reach);
}
